//
// Read subsampling and strand inferring options
//

process {

    withName: 'FQ_LINT_AFTER_TRIMMING' {
        ext.prefix = { "${meta.id}.trimmed" }
    }

    withName: 'FQ_LINT_AFTER_BBSPLIT' {
        ext.prefix = { "${meta.id}.bbsplit" }
    }

    withName: 'FQ_LINT_AFTER_RIBO_REMOVAL' {
        ext.prefix = { "${meta.id}.fq_lint_after_ribo_removal" }
    }

    withName: 'FQ_SUBSAMPLE' {
        ext.args   = '--record-count 1000000 --seed 1'
        ext.prefix = { "${meta.id}.subsampled" }
        publishDir = [
            enabled: false
        ]
    }

    withName: '.*:FASTQ_SUBSAMPLE_FQ_SALMON:SALMON_QUANT' {
        ext.args   = '--skipQuant'
        publishDir = [
            enabled: false
        ]
    }
    withName: 'SORTMERNA' {
        ext.args  = '--index 0'
    }
    withName: 'SORTMERNA_INDEX' {
        ext.args  = '--index 1'
    }
    withName: 'RIBODETECTOR' {
        ext.prefix = { "${meta.id}.ribodetector" }
        ext.args = '--seed 1'
    }
    withName: 'BOWTIE2_ALIGN' {
        ext.prefix = { "${meta.id}.bowtie2_rrna" }
        ext.args = '--very-sensitive-local --seed 1 --reorder'
    }
    withName: 'BOWTIE2_ALIGN_PE' {
        ext.prefix = { "${meta.id}.bowtie2_rrna" }
        ext.args = '--very-sensitive-local --seed 1 --reorder'
    }
    withName: 'SAMTOOLS_VIEW_BOWTIE2' {
        ext.prefix = { "${meta.id}.bowtie2_unmapped" }
        ext.args = '-f 12'  // Keep only pairs where BOTH mates are unmapped
    }
    withName: 'SAMTOOLS_FASTQ_BOWTIE2' {
        ext.prefix = { "${meta.id}.bowtie2_filtered" }
    }
    withName: 'SEQKIT_REPLACE' {
        ext.args = '--pattern "^(.+)" --replacement "{fbn}_\\$1"'
        ext.prefix = { "${meta.id}_prefixed" }
    }
    withName: 'SEQKIT_REPLACE_U2T' {
        ext.args = '--by-seq --pattern "[Uu]" --replacement "T"'
        ext.prefix = { "${meta.id}_converted" }
    }
}

includeConfig 'nextflow.config'

//
// Disable SALMON processes within FASTQ_SUBSAMPLE_FQ_SALMON to simulate
// a scenario where Salmon fails to produce lib_format_counts output
//

process {
    withName: '.*:FASTQ_SUBSAMPLE_FQ_SALMON:SALMON_INDEX' {
        ext.when = false
    }
    withName: '.*:FASTQ_SUBSAMPLE_FQ_SALMON:SALMON_QUANT' {
        ext.when = false
    }
}
